const body = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const prompt = String(body.prompt ?? body.promptRaw ?? '').trim();
if (!prompt) {
  throw new Error('Missing prompt');
}
const generation = body.generation && typeof body.generation === 'object' ? body.generation : {};
const mode = String(body.mode ?? 'text-to-image');
const model = String(body.model ?? 'gpt-5.4-mini').trim() || 'gpt-5.4-mini';
const toolModel = String(body.toolModel ?? 'gpt-image-2').trim() || 'gpt-image-2';
const executionId = String($execution?.id ?? '').trim();
const content = [{ type: 'input_text', text: prompt }];

const parseResolutionSize = (resolution) => {
  const match = String(resolution ?? '').trim().match(/^(\d+)x(\d+)$/i);
  if (!match) {
    return null;
  }
  const width = Number.parseInt(match[1], 10);
  const height = Number.parseInt(match[2], 10);
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
    return null;
  }
  return { width, height };
};

const inferOrientationFromResolution = (resolution) => {
  const parsed = parseResolutionSize(resolution);
  if (!parsed) {
    return 'square';
  }
  if (parsed.width === parsed.height) {
    return 'square';
  }
  return parsed.width > parsed.height ? 'landscape' : 'portrait';
};

const inferOrientationFromAspectRatio = (aspectRatio) => {
  const normalized = String(aspectRatio ?? '').trim();
  if (!normalized || normalized === 'auto') {
    return null;
  }
  if (normalized === '1:1') {
    return 'square';
  }
  if (['4:3', '3:2', '16:9', '21:9'].includes(normalized)) {
    return 'landscape';
  }
  if (['3:4', '2:3', '9:16'].includes(normalized)) {
    return 'portrait';
  }
  return null;
};

const isValidToolSize = (resolution) => {
  const parsed = parseResolutionSize(resolution);
  if (!parsed) {
    return false;
  }
  const { width, height } = parsed;
  if (width % 16 !== 0 || height % 16 !== 0) {
    return false;
  }
  if (Math.max(width, height) > 3840) {
    return false;
  }
  const pixelCount = width * height;
  if (pixelCount < 655360 || pixelCount > 8294400) {
    return false;
  }
  const ratio = Math.max(width, height) / Math.min(width, height);
  return ratio <= 3;
};

const normalizeToolSize = (widthValue, heightValue) => {
  let width = Number(widthValue);
  let height = Number(heightValue);
  if (!Number.isFinite(width) || !Number.isFinite(height) || width <= 0 || height <= 0) {
    return null;
  }
  const snap = (value) => Math.max(16, Math.round(value / 16) * 16);
  for (let attempt = 0; attempt < 10; attempt += 1) {
    const ratio = Math.max(width, height) / Math.min(width, height);
    if (ratio > 3) {
      if (width > height) {
        height = width / 3;
      } else {
        width = height / 3;
      }
    }
    const maxEdge = Math.max(width, height);
    if (maxEdge > 3840) {
      const scale = 3840 / maxEdge;
      width *= scale;
      height *= scale;
    }
    const pixelCount = width * height;
    if (pixelCount > 8294400) {
      const scale = Math.sqrt(8294400 / pixelCount);
      width *= scale;
      height *= scale;
    } else if (pixelCount < 655360) {
      const scale = Math.sqrt(655360 / pixelCount);
      width *= scale;
      height *= scale;
    }
    width = snap(width);
    height = snap(height);
    const normalized = width + 'x' + height;
    if (isValidToolSize(normalized)) {
      return normalized;
    }
  }
  return null;
};

const extractPromptResolutionCandidates = (promptText) => {
  const source = String(promptText ?? '');
  const candidates = [];
  const collect = (pattern, widthIndex, heightIndex) => {
    for (const match of source.matchAll(pattern)) {
      candidates.push({
        width: match[widthIndex],
        height: match[heightIndex],
        matchedText: match[0],
        index: match.index ?? 0,
      });
    }
  };
  collect(/(^|[^\d])(\d{3,5})\s*(?:x|\*)\s*(\d{3,5})\s*(?:px)?(?!\d)/gi, 2, 3);
  collect(/(?<!\d)(\d{3,5})\s*by\s*(\d{3,5})\s*(?:px)?(?!\d)/gi, 1, 2);
  collect(/(?:width|w)\s*[:=]?\s*(\d{3,5})\s*(?:px)?\s*(?:[,;\/-]?\s*)?(?:height|h)\s*[:=]?\s*(\d{3,5})\s*(?:px)?/gi, 1, 2);
  collect(/(?:height|h)\s*[:=]?\s*(\d{3,5})\s*(?:px)?\s*(?:[,;\/-]?\s*)?(?:width|w)\s*[:=]?\s*(\d{3,5})\s*(?:px)?/gi, 2, 1);
  return candidates.sort((left, right) => left.index - right.index);
};

const resolvePromptToolSize = (promptText) => {
  const candidates = extractPromptResolutionCandidates(promptText);
  for (let index = candidates.length - 1; index >= 0; index -= 1) {
    const candidate = candidates[index];
    const normalized = normalizeToolSize(candidate.width, candidate.height);
    if (normalized) {
      return { size: normalized, matchedText: candidate.matchedText };
    }
  }
  return null;
};

const resolveToolSize = () => {
  const explicitToolSize = String(generation.toolSize ?? '').trim();
  const resolutionPriority = String(generation.resolutionPriority ?? '').trim();
  if ((resolutionPriority === 'source' || generation.keepSourceAspectRatio === true) && isValidToolSize(explicitToolSize)) {
    return explicitToolSize;
  }
  const promptOverride = resolvePromptToolSize(body.promptRaw) ?? resolvePromptToolSize(!body.promptRaw ? prompt : '');
  if (promptOverride?.size) {
    return promptOverride.size;
  }
  if (isValidToolSize(explicitToolSize)) {
    return explicitToolSize;
  }
  const resolution = String(generation.resolution ?? '').trim();
  if (isValidToolSize(resolution)) {
    return resolution;
  }
  const orientation = inferOrientationFromAspectRatio(generation.aspectRatio) ?? inferOrientationFromResolution(resolution);
  if (orientation === 'landscape') {
    return '2048x1152';
  }
  if (orientation === 'portrait') {
    return '1152x2048';
  }
  return '1024x1024';
};

const normalizeReferenceItems = () => {
  const sourceItems = Array.isArray(body.sourceItems)
    ? body.sourceItems.filter((item) => item && typeof item === 'object')
    : [];
  if (sourceItems.length > 0) {
    return sourceItems;
  }
  const legacySource = body.source && typeof body.source === 'object' ? body.source : null;
  return legacySource ? [legacySource] : [];
};

const referenceItems = normalizeReferenceItems();
const normalizedReferenceLabels = [];
if (mode === 'image-to-image') {
  if (referenceItems.length === 0) {
    throw new Error('Image-to-image requires at least one sourceItems entry or legacy source');
  }

  let appendedReferenceCount = 0;
  for (const item of referenceItems) {
    const imageBase64 = String(item.imageBase64 ?? '').trim();
    const imageUrl = String(item.imageUrl ?? '').trim();
    const mimeType = String(item.mimeType ?? 'image/png').trim() || 'image/png';
    const label = String(item.label ?? '').trim();

    if (imageBase64) {
      content.push({
        type: 'input_image',
        image_url: imageBase64.startsWith('data:image/') ? imageBase64 : ('data:' + mimeType + ';base64,' + imageBase64),
      });
      appendedReferenceCount += 1;
      if (label) normalizedReferenceLabels.push(label);
      continue;
    }

    if (imageUrl) {
      content.push({
        type: 'input_image',
        image_url: imageUrl,
      });
      appendedReferenceCount += 1;
      if (label) normalizedReferenceLabels.push(label);
    }
  }

  if (appendedReferenceCount === 0) {
    throw new Error('Image-to-image requires usable sourceItems.imageBase64 or sourceItems.imageUrl');
  }
}
if (mode === 'image-to-image' && referenceItems.length > 0 && !/Image-to-image reference instructions:/i.test(content[0].text)) {
  const referenceLines = referenceItems.map((item, index) => {
    const label = String(item.label ?? ('reference ' + (index + 1))).trim() || ('reference ' + (index + 1));
    const role = String(item.role ?? (index === 0 ? 'subject' : 'style')).trim() || (index === 0 ? 'subject' : 'style');
    const note = String(item.note ?? '').trim();
    return (index + 1) + '. ' + label + ' (' + role + ')' + (note ? ': ' + note : '');
  }).join('\n');
  const rawStrength = Number(generation.strength ?? 0.65);
  const strength = Number.isFinite(rawStrength) ? Math.max(0, Math.min(1, rawStrength)) : 0.65;
  const strengthPercent = Math.round(strength * 100);
  const influence = strength < 0.4
    ? 'loose influence: borrow broad cues only'
    : strength > 0.75
      ? 'close influence: preserve the requested subject/style cues, but still create a new image'
      : 'balanced influence: keep useful subject/style cues while following the new prompt';
  content[0].text = prompt + '\n\nImage-to-image reference instructions:\n'
    + '- Use the attached reference image(s) as guidance only; do not return, copy, or lightly re-save the reference image unchanged.\n'
    + '- Generate a new image that follows the prompt above. The final result must be visibly transformed from the input reference.\n'
    + '- Reference strength: ' + strengthPercent + '% (' + influence + ').\n'
    + '- Reference roles:\n' + referenceLines;
}
const promptToolOverride = resolvePromptToolSize(body.promptRaw) ?? resolvePromptToolSize(!body.promptRaw ? prompt : '');
const resolvedToolSize = resolveToolSize();
const requestPayload = {
  model,
  stream: true,
  input: [
    {
      role: 'user',
      content,
    },
  ],
  tool_choice: {
    type: 'image_generation',
  },
  tools: [
    {
      type: 'image_generation',
      model: toolModel,
      size: resolvedToolSize,
      quality: String(generation.quality ?? '').trim() === 'high' ? 'high' : 'medium',
      output_format: String(generation.outputFormat ?? 'png').trim() || 'png',
    },
  ],
};
return [{
  json: {
    requestPayload,
    requestMeta: {
      requestId: String(body.requestId ?? ''),
      executionId,
      mode,
      model,
      toolModel,
      prompt: prompt.slice(0, 400),
      sourceCount: referenceItems.length,
      sourceLabels: normalizedReferenceLabels.slice(0, 12),
      usesLegacySource: !Array.isArray(body.sourceItems) || body.sourceItems.length === 0,
      requestedResolution: String(generation.resolution ?? '').trim(),
      requestedAspectRatio: String(generation.aspectRatio ?? '').trim() || 'auto',
      promptResolvedToolSize: promptToolOverride?.size ?? '',
      promptResolvedText: promptToolOverride?.matchedText ?? '',
      resolvedToolSize,
    },
  },
}];

const executionId = String($json.requestMeta?.executionId ?? '').trim();
const mode = String($json.requestMeta?.mode ?? 'text-to-image');
return [{
  json: {
    ...$json,
    responseBody: {
      ok: true,
      status: 'accepted',
      queued: true,
      jobId: executionId,
      mode,
      message: executionId
        ? '\u4efb\u52a1\u5df2\u53d7\u7406\uff0c\u6b63\u5728\u7531 n8n \u540e\u53f0\u751f\u6210\u56fe\u7247\uff0c\u8bf7\u7b49\u5f85\u72b6\u6001\u8f6e\u8be2\u7ed3\u679c\u3002'
        : '\u4efb\u52a1\u5df2\u53d7\u7406\uff0c\u4f46\u5f53\u524d\u672a\u62ff\u5230 executionId\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002',
    },
  },
}];

const envelope = ($json && typeof $json === 'object') ? $json : { response: $json };
const source = (envelope.response && typeof envelope.response === 'object') ? envelope.response : envelope;
const upstreamRoute = String(envelope.upstreamRoute ?? envelope.provider ?? 'asxs-primary');
const fallbackUsed = Boolean(envelope.fallbackUsed);
const primaryFailure = envelope.primaryFailure && typeof envelope.primaryFailure === 'object' ? envelope.primaryFailure : null;
const ERROR_TEXT_PATTERN = /service unavailable|\u5f53\u524d\u670d\u52a1\u6682\u4e0d\u53ef\u7528|\u5168\u90e8\u6e20\u9053\u4e0d\u53ef\u63d0\u4f9b\u5f53\u524d\u6a21\u578b|\u5f53\u524d\u6a21\u578b\u4e0d\u53ef\u7528|model unavailable|unsupported model|NodeApiError|bad gateway|gateway timeout|cloudflare/i;

const buildFailureMessage = (message) => {
  if (fallbackUsed && primaryFailure?.message) {
    return `\u4e3b\u901a\u9053 ASXS \u5931\u8d25\uff1a${primaryFailure.message}\uff1b\u5907\u7528\u901a\u9053 OpenAI \u5b98\u65b9\u5931\u8d25\uff1a${message}`;
  }
  if (!fallbackUsed && upstreamRoute === 'asxs-primary' && !/^ASXS /.test(message)) {
    return `ASXS \u751f\u56fe\u5931\u8d25\uff1a${message}`;
  }
  return message;
};

const buildFailure = (status, message, rawPreview, httpCode = null, eventTypes = [], hasOutputItemDone = false) => [{
  json: {
    ok: false,
    status,
    message: buildFailureMessage(message),
    httpCode,
    imageCount: 0,
    images: [],
    outputText: '',
    eventTypes,
    hasOutputItemDone,
    rawPreview: String(rawPreview || '').slice(0, 12000),
    upstreamRoute,
    fallbackUsed,
    primaryFailure,
  },
}];

if (source && typeof source === 'object') {
  const upstreamError = source.error || source.errors || null;
  if (upstreamError) {
    const rawMessage = typeof upstreamError === 'string'
      ? upstreamError
      : typeof source.message === 'string'
        ? source.message
        : typeof upstreamError.message === 'string'
          ? upstreamError.message
          : JSON.stringify(upstreamError).slice(0, 2000);
    const httpCode = Number(source.httpCode ?? source.statusCode ?? upstreamError.httpCode ?? 0);
    const isServiceUnavailable = httpCode === 503 || ERROR_TEXT_PATTERN.test(rawMessage);
    const message = isServiceUnavailable
      ? '\u7f51\u5173\u7e41\u5fd9\u6216\u4e0a\u6e38\u670d\u52a1\u6682\u65f6\u4e0d\u53ef\u7528\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002\u539f\u59cb\u4fe1\u606f\uff1a' + rawMessage
      : rawMessage;
    return buildFailure(
      isServiceUnavailable ? 'upstream_service_unavailable' : 'upstream_error',
      message,
      JSON.stringify(source),
      httpCode || null,
    );
  }
}

const httpCode = Number(source.httpCode ?? source.statusCode ?? source.code ?? 0) || null;
const raw = typeof source.body === 'string'
  ? source.body
  : typeof source.data === 'string'
    ? source.data
    : typeof source === 'string'
      ? source
      : JSON.stringify(source);

if (typeof source.statusCode === 'number' && source.statusCode >= 400) {
  return buildFailure('http_error', raw.slice(0, 2000), raw, source.statusCode || null);
}

const eventTypes = new Set();
const outputTextChunks = [];
const failureMessages = [];
const images = [];
const imageSet = new Set();
let hasOutputItemDone = false;
let hasFailureEvent = false;

const toDataUrl = (base64, mimeType = 'image/png') => {
  const normalized = String(base64 || '').replace(/\s+/g, '');
  if (!normalized) return '';
  return normalized.startsWith('data:image/') ? normalized : ('data:' + mimeType + ';base64,' + normalized);
};

const pushText = (value) => {
  const text = String(value ?? '').trim();
  if (!text || text.length < 2 || text.startsWith('data:image/')) return;
  if (!outputTextChunks.includes(text)) outputTextChunks.push(text);
};

const pushFailureMessage = (value) => {
  const text = String(value ?? '').trim();
  if (!text || text.length < 2) return;
  if (!failureMessages.includes(text)) failureMessages.push(text);
  pushText(text);
};

const addImage = (base64, mimeType = 'image/png') => {
  const src = toDataUrl(base64, mimeType);
  if (!src || imageSet.has(src)) return;
  imageSet.add(src);
  images.push({ src, mimeType });
};

const parseSsePayload = (rawText) => {
  const normalized = String(rawText ?? '').replace(/\r\n/g, '\n').replace(/\r/g, '\n');
  const blocks = normalized.split('\n\n').map((item) => item.trim()).filter(Boolean);
  const parsedItems = [];
  let parsedAnyBlock = false;

  for (const block of blocks) {
    const lines = block.split('\n');
    let eventType = '';
    const dataLines = [];
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith(':')) continue;
      if (trimmed.startsWith('event:')) {
        eventType = trimmed.slice(6).trim();
        continue;
      }
      if (trimmed.startsWith('data:')) {
        dataLines.push(trimmed.slice(5).trim());
      }
    }
    if (!dataLines.length) continue;
    parsedAnyBlock = true;
    const merged = dataLines.join('\n').trim();
    if (!merged || merged === '[DONE]') continue;
    try {
      const payload = JSON.parse(merged);
      if (payload && typeof payload === 'object') {
        if (eventType && typeof payload.event !== 'string') payload.event = eventType;
        parsedItems.push(payload);
      } else if (eventType) {
        parsedItems.push({ event: eventType, data: payload });
      } else {
        parsedItems.push(payload);
      }
    } catch {
      if (eventType) {
        parsedItems.push({ event: eventType, data: merged });
      } else {
        parsedItems.push(merged);
      }
    }
  }

  if (!parsedAnyBlock) return rawText;
  return parsedItems.length === 1 ? parsedItems[0] : parsedItems;
};

const parseStructured = (value) => {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed || trimmed.startsWith('data:image/')) return value;
  if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
    try {
      return JSON.parse(trimmed);
    } catch {
      return value;
    }
  }
  if (trimmed.includes('event:') || trimmed.includes('data:')) {
    return parseSsePayload(trimmed);
  }
  return value;
};

const walk = (node) => {
  if (node === null || node === undefined) return;
  if (typeof node === 'string') {
    const parsed = parseStructured(node);
    if (parsed !== node) {
      walk(parsed);
      return;
    }
    pushText(node);
    return;
  }
  if (Array.isArray(node)) {
    node.forEach(walk);
    return;
  }
  if (typeof node !== 'object') return;

  const nodeType = typeof node.type === 'string' ? node.type : '';
  const nodeEvent = typeof node.event === 'string' ? node.event : '';
  if (nodeType) eventTypes.add(nodeType);
  if (nodeEvent) eventTypes.add(nodeEvent);
  if (nodeType === 'response.output_item.done' || nodeEvent === 'response.output_item.done') {
    hasOutputItemDone = true;
  }

  const normalizedEvent = `${nodeType} ${nodeEvent} ${String(node.code ?? '')}`.toLowerCase();
  if (
    normalizedEvent.includes('response.failed')
    || normalizedEvent.includes('server_error')
    || normalizedEvent.includes('invalid_request_error')
    || normalizedEvent.includes('rate_limit_error')
    || normalizedEvent.includes('image_generation_failed')
    || normalizedEvent === 'error'
    || normalizedEvent.endsWith('.error')
  ) {
    hasFailureEvent = true;
  }

  const nodeFailureMessage = typeof node.error === 'string'
    ? node.error
    : typeof node.message === 'string'
      ? node.message
      : node.error && typeof node.error === 'object' && typeof node.error.message === 'string'
        ? node.error.message
        : '';
  if (nodeFailureMessage && hasFailureEvent) {
    pushFailureMessage(nodeFailureMessage);
  }

  const mimeType = typeof node.mime_type === 'string'
    ? node.mime_type
    : typeof node.mimeType === 'string'
      ? node.mimeType
      : (typeof node.output_format === 'string' && node.output_format.toLowerCase() === 'jpeg' ? 'image/jpeg' : 'image/png');

  const imageLike = node.src || node.url;
  if (typeof imageLike === 'string' && /^(data:image\/|https?:\/\/)/i.test(imageLike.trim())) {
    if (imageLike.trim().startsWith('data:image/')) {
      addImage(imageLike, mimeType);
    } else {
      images.push({ src: imageLike.trim(), mimeType: mimeType || 'image/png' });
    }
  }

  if (nodeType === 'image_generation_call') {
    const result = node.result;
    const outputFormat = typeof node.output_format === 'string' ? node.output_format : '';
    const resultMimeType = mimeType || (outputFormat.toLowerCase() === 'jpeg' ? 'image/jpeg' : 'image/png');
    if (result !== null && result !== undefined) {
      if (typeof result === 'string' && result.trim().length > 40) {
        const parsed = parseStructured(result);
        if (parsed !== result) {
          walk(parsed);
        } else if (result.startsWith('data:image/')) {
          addImage(result, resultMimeType);
        } else {
          addImage(result, resultMimeType);
        }
      } else {
        walk(result);
      }
    }
  }

  for (const inlineKey of ['inlineData', 'inline_data']) {
    const inlineValue = node[inlineKey];
    if (inlineValue && typeof inlineValue === 'object') {
      const data = inlineValue.data;
      const inlineMime = inlineValue.mimeType || inlineValue.mime_type || mimeType;
      if (typeof data === 'string' && data.trim().length > 40) {
        addImage(data, inlineMime || 'image/png');
      }
    }
  }

  for (const key of ['b64_json', 'b64', 'image_base64', 'imageBase64', 'base64', 'image']) {
    const value = node[key];
    if (typeof value === 'string' && value.trim().length > 40) {
      addImage(value, mimeType || 'image/png');
    }
  }

  for (const value of Object.values(node)) {
    walk(value);
  }
};

const parsedRaw = parseStructured(raw);
if (parsedRaw !== raw) {
  walk(parsedRaw);
} else {
  try {
    walk(JSON.parse(raw));
  } catch {
    walk(raw);
  }
}

const outputText = outputTextChunks.join('\n').slice(0, 6000);
const eventTypeList = Array.from(eventTypes);
const rawPreview = raw.slice(0, 12000);
const streamedFailureMessage = failureMessages[0]
  || outputTextChunks.find((line) => /failed|error|unable|process your request|\u670d\u52a1|\u4e0d\u53ef\u7528/i.test(line))
  || '';

if (images.length === 0 && (hasFailureEvent || ERROR_TEXT_PATTERN.test(`${outputText}\n${rawPreview}`))) {
  return buildFailure(
    'upstream_error',
    streamedFailureMessage || outputText || rawPreview.slice(0, 500),
    rawPreview,
    httpCode,
    eventTypeList,
    hasOutputItemDone,
  );
}

const recentEventTypes = eventTypeList.length > 0 ? eventTypeList.slice(0, 12).join(', ') : '\u672a\u89e3\u6790\u5230\u4e8b\u4ef6\u7c7b\u578b';
const noImageMessage = hasOutputItemDone
  ? `\u68c0\u6d4b\u5230 response.output_item.done\uff0c\u4f46\u4e8b\u4ef6\u4e2d\u672a\u63d0\u53d6\u5230\u53ef\u7528\u56fe\u7247\u6570\u636e\uff08item.result \u53ef\u80fd\u4e3a\u7a7a\uff09\u3002\u4e8b\u4ef6\u7c7b\u578b\uff1a${recentEventTypes}`
  : `\u672a\u68c0\u6d4b\u5230 response.output_item.done\u3002\u4e8b\u4ef6\u7c7b\u578b\uff1a${recentEventTypes}`;
const message = images.length > 0
  ? (fallbackUsed ? `\u5b98\u65b9 OpenAI fallback \u751f\u56fe\u6210\u529f\uff08${images.length} \u5f20\uff09` : `ASXS \u751f\u56fe\u6210\u529f\uff08${images.length} \u5f20\uff09`)
  : (fallbackUsed && primaryFailure?.message
      ? `\u4e3b\u901a\u9053 ASXS \u5931\u8d25\uff1a${primaryFailure.message}\uff1b\u5907\u7528\u901a\u9053\u5df2\u8fd4\u56de\u54cd\u5e94\uff0c\u4f46${noImageMessage}`
      : noImageMessage);

return [{
  json: {
    ok: images.length > 0,
