const parsedRaw = parseStructured(raw);
if (parsedRaw !== raw) {
  walk(parsedRaw);
} else {
  try {
    walk(JSON.parse(raw));
  } catch {
    walk(raw);
  }
}

const outputText = outputTextChunks.join('\n').slice(0, 6000);
const eventTypeList = Array.from(eventTypes);
const rawPreview = raw.slice(0, 12000);
const streamedFailureMessage = failureMessages[0]
  || outputTextChunks.find((line) => /failed|error|unable|process your request|\u670d\u52a1|\u4e0d\u53ef\u7528/i.test(line))
  || '';

if (images.length === 0 && (hasFailureEvent || ERROR_TEXT_PATTERN.test(`${outputText}\n${rawPreview}`))) {
  return buildFailure(
    'upstream_error',
    streamedFailureMessage || outputText || rawPreview.slice(0, 500),
    rawPreview,
    httpCode,
    eventTypeList,
    hasOutputItemDone,
  );
}

const recentEventTypes = eventTypeList.length > 0 ? eventTypeList.slice(0, 12).join(', ') : '\u672a\u89e3\u6790\u5230\u4e8b\u4ef6\u7c7b\u578b';
const noImageMessage = hasOutputItemDone
  ? `\u68c0\u6d4b\u5230 response.output_item.done\uff0c\u4f46\u4e8b\u4ef6\u4e2d\u672a\u63d0\u53d6\u5230\u53ef\u7528\u56fe\u7247\u6570\u636e\uff08item.result \u53ef\u80fd\u4e3a\u7a7a\uff09\u3002\u4e8b\u4ef6\u7c7b\u578b\uff1a${recentEventTypes}`
  : `\u672a\u68c0\u6d4b\u5230 response.output_item.done\u3002\u4e8b\u4ef6\u7c7b\u578b\uff1a${recentEventTypes}`;
const message = images.length > 0
  ? (fallbackUsed ? `\u5b98\u65b9 OpenAI fallback \u751f\u56fe\u6210\u529f\uff08${images.length} \u5f20\uff09` : `ASXS \u751f\u56fe\u6210\u529f\uff08${images.length} \u5f20\uff09`)
  : (fallbackUsed && primaryFailure?.message
      ? `\u4e3b\u901a\u9053 ASXS \u5931\u8d25\uff1a${primaryFailure.message}\uff1b\u5907\u7528\u901a\u9053\u5df2\u8fd4\u56de\u54cd\u5e94\uff0c\u4f46${noImageMessage}`
      : noImageMessage);

return [{
  json: {
    ok: images.length > 0,
    status: images.length > 0 ? 'completed' : 'no_image',
    message,
    imageCount: images.length,
    images,
    outputText,
    eventTypes: eventTypeList,
    hasOutputItemDone,
    rawPreview,
    upstreamRoute,
    fallbackUsed,
    primaryFailure,
  },
}];

const source = ($json && typeof $json === 'object') ? $json : { body: $json };
const ERROR_TEXT_PATTERN = /service unavailable|\u5f53\u524d\u670d\u52a1\u6682\u4e0d\u53ef\u7528|\u5168\u90e8\u6e20\u9053\u4e0d\u53ef\u63d0\u4f9b\u5f53\u524d\u6a21\u578b|\u5f53\u524d\u6a21\u578b\u4e0d\u53ef\u7528|model unavailable|unsupported model|NodeApiError|bad gateway|gateway timeout|cloudflare/i;

const upstreamError = source.error || source.errors || null;
const raw = typeof source.body === 'string'
  ? source.body
  : typeof source.data === 'string'
    ? source.data
    : typeof source === 'string'
      ? source
      : JSON.stringify(source);
const httpCode = Number(source.httpCode ?? source.statusCode ?? source.code ?? upstreamError?.httpCode ?? 0) || null;
const rawMessage = typeof upstreamError === 'string'
  ? upstreamError
  : typeof source.message === 'string'
    ? source.message
    : typeof upstreamError?.message === 'string'
      ? upstreamError.message
      : raw.slice(0, 2000);
const transportFailure = Boolean(upstreamError) || (typeof source.statusCode === 'number' && source.statusCode >= 400);
const gatewayFailure = ERROR_TEXT_PATTERN.test(`${rawMessage}\n${raw}`);
const hasOutputItemDone = /response\.output_item\.done/.test(raw);
const hasImageGenerationCall = /image_generation_call/.test(raw);
const hasLikelyImageResult = /"result"\s*:\s*"(?:data:image\/[^;]+;base64,)?[A-Za-z0-9+/=]{120,}"/.test(raw)
  || /"b64_json"\s*:\s*"[A-Za-z0-9+/=]{120,}"/.test(raw)
  || /"imageBase64"\s*:\s*"[A-Za-z0-9+/=]{120,}"/.test(raw)
  || /"inlineData"\s*:\s*\{[^}]*"data"\s*:\s*"[A-Za-z0-9+/=]{120,}"/s.test(raw);
const hasFailureEvent = /response\.failed/.test(raw)
  || /server_error/.test(raw)
  || /invalid_request_error/.test(raw)
  || /rate_limit_error/.test(raw)
  || /"type"\s*:\s*"error"/.test(raw)
  || /"event"\s*:\s*"error"/.test(raw);
const failureMessageMatch = raw.match(/(?:The service failed to process your request[^"\n]*|service unavailable[^"\n]*|server_error[^"\n]*|model unavailable[^"\n]*)/i);
const streamedFailureMessage = failureMessageMatch ? failureMessageMatch[0] : rawMessage;
const streamFailure = !transportFailure && hasFailureEvent && !hasLikelyImageResult;
const noImageCompletion = !transportFailure && (hasOutputItemDone || hasFailureEvent) && (!hasImageGenerationCall || !hasLikelyImageResult);
const shouldFallback = transportFailure || gatewayFailure || streamFailure || noImageCompletion;
const primaryFailureMessage = streamFailure
  ? (streamedFailureMessage || 'ASXS returned a streamed failure response; using OpenAI official fallback.')
  : (noImageCompletion
      ? 'ASXS returned a completed response without usable image data; using OpenAI official fallback.'
      : rawMessage);

return [{
  json: {
    shouldFallback,
    primaryResponse: source,
    primaryFailure: shouldFallback
      ? {
          provider: 'asxs-primary',
          httpCode,
          message: String(primaryFailureMessage || rawMessage || 'ASXS generate failed').slice(0, 2000),
          rawPreview: String(raw || '').slice(0, 4000),
        }
      : null,
  },
}];

return [{
  json: {
    upstreamRoute: 'asxs-primary',
    fallbackUsed: false,
    response: $json.primaryResponse ?? $json,
    primaryFailure: $json.primaryFailure ?? null,
  },
}];

const primary = $('Evaluate Primary Generate Result').first().json.primaryFailure ?? null;
return [{
  json: {
    upstreamRoute: 'openai-fallback',
    fallbackUsed: true,
    response: $json,
    primaryFailure: primary,
  },
}];
